/*
 * Lightweight local Mermaid-compatible demo renderer.
 * Supports basic stateDiagram transitions like: A --> B
 */
(function () {
  "use strict";

  var config = { startOnLoad: false };

  function uniqPush(list, value) {
    if (value && list.indexOf(value) === -1) {
      list.push(value);
    }
  }

  function parseStateDiagram(source) {
    var lines = source.split(/\r?\n/);
    var states = [];
    var transitions = [];

    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if (!line || line.indexOf("stateDiagram") === 0 || line.indexOf("%%") === 0) {
        continue;
      }

      var arrowMatch = line.match(/^([^\-:]+?)\s*-->\s*([^:]+?)(?:\s*:\s*(.+))?$/);
      if (!arrowMatch) {
        continue;
      }

      var from = arrowMatch[1].trim();
      var to = arrowMatch[2].trim();
      var label = arrowMatch[3] ? arrowMatch[3].trim() : "";

      uniqPush(states, from);
      uniqPush(states, to);
      transitions.push({ from: from, to: to, label: label });
    }

    return { states: states, transitions: transitions };
  }

  function createSvg(tag) {
    return document.createElementNS("http://www.w3.org/2000/svg", tag);
  }

  function buildDiagram(parsed) {
    var boxW = 150;
    var boxH = 44;
    var gap = 70;
    var pad = 24;
    var states = parsed.states;
    var transitions = parsed.transitions;

    var width = Math.max(380, pad * 2 + states.length * boxW + Math.max(0, states.length - 1) * gap);
    var height = 220;

    var svg = createSvg("svg");
    svg.setAttribute("viewBox", "0 0 " + width + " " + height);
    svg.setAttribute("width", "100%");
    svg.setAttribute("height", String(height));
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", "State machine diagram");

    var defs = createSvg("defs");
    var marker = createSvg("marker");
    marker.setAttribute("id", "arrowhead");
    marker.setAttribute("viewBox", "0 0 10 10");
    marker.setAttribute("refX", "9");
    marker.setAttribute("refY", "5");
    marker.setAttribute("markerWidth", "8");
    marker.setAttribute("markerHeight", "8");
    marker.setAttribute("orient", "auto-start-reverse");

    var arrowPath = createSvg("path");
    arrowPath.setAttribute("d", "M 0 0 L 10 5 L 0 10 z");
    arrowPath.setAttribute("fill", "#0f172a");
    marker.appendChild(arrowPath);
    defs.appendChild(marker);
    svg.appendChild(defs);

    var positions = {};
    for (var i = 0; i < states.length; i++) {
      var x = pad + i * (boxW + gap);
      var y = 90;
      positions[states[i]] = { x: x, y: y };

      var rect = createSvg("rect");
      rect.setAttribute("x", String(x));
      rect.setAttribute("y", String(y));
      rect.setAttribute("rx", "10");
      rect.setAttribute("ry", "10");
      rect.setAttribute("width", String(boxW));
      rect.setAttribute("height", String(boxH));
      rect.setAttribute("fill", "#f8fafc");
      rect.setAttribute("stroke", "#0f172a");
      rect.setAttribute("stroke-width", "1.5");
      svg.appendChild(rect);

      var text = createSvg("text");
      text.setAttribute("x", String(x + boxW / 2));
      text.setAttribute("y", String(y + 28));
      text.setAttribute("text-anchor", "middle");
      text.setAttribute("font-size", "15");
      text.setAttribute("font-family", "Verdana, sans-serif");
      text.setAttribute("fill", "#0f172a");
      text.textContent = states[i];
      svg.appendChild(text);
    }

    for (var j = 0; j < transitions.length; j++) {
      var t = transitions[j];
      var fromPos = positions[t.from];
      var toPos = positions[t.to];
      if (!fromPos || !toPos) {
        continue;
      }

      var fromRight = fromPos.x + boxW;
      var fromLeft = fromPos.x;
      var toRight = toPos.x + boxW;
      var toLeft = toPos.x;
      var yMid = fromPos.y + boxH / 2;

      var line = createSvg("line");
      if (toPos.x >= fromPos.x) {
        line.setAttribute("x1", String(fromRight));
        line.setAttribute("y1", String(yMid));
        line.setAttribute("x2", String(toLeft));
        line.setAttribute("y2", String(yMid));
      } else {
        line.setAttribute("x1", String(fromLeft));
        line.setAttribute("y1", String(yMid + 12));
        line.setAttribute("x2", String(toRight));
        line.setAttribute("y2", String(yMid + 12));
      }
      line.setAttribute("stroke", "#0f172a");
      line.setAttribute("stroke-width", "1.5");
      line.setAttribute("marker-end", "url(#arrowhead)");
      svg.appendChild(line);

      if (t.label) {
        var lx = (parseFloat(line.getAttribute("x1")) + parseFloat(line.getAttribute("x2"))) / 2;
        var ly = (parseFloat(line.getAttribute("y1")) + parseFloat(line.getAttribute("y2"))) / 2 - 8;
        var ltext = createSvg("text");
        ltext.setAttribute("x", String(lx));
        ltext.setAttribute("y", String(ly));
        ltext.setAttribute("text-anchor", "middle");
        ltext.setAttribute("font-size", "12");
        ltext.setAttribute("font-family", "Verdana, sans-serif");
        ltext.setAttribute("fill", "#334155");
        ltext.textContent = t.label;
        svg.appendChild(ltext);
      }
    }

    return svg;
  }

  function renderElement(el) {
    var source = el.textContent || "";
    var parsed = parseStateDiagram(source);
    if (!parsed.states.length) {
      return;
    }
    el.innerHTML = "";
    el.appendChild(buildDiagram(parsed));
  }

  function run(target) {
    var root = target && target.querySelectorAll ? target : document;
    var elements = root.querySelectorAll(".mermaid");
    for (var i = 0; i < elements.length; i++) {
      renderElement(elements[i]);
    }
  }

  window.mermaid = {
    initialize: function (opts) {
      config = Object.assign(config, opts || {});
      if (config.startOnLoad) {
        window.addEventListener("DOMContentLoaded", function () {
          run(document);
        });
      }
    },
    run: function (opts) {
      run(opts && opts.nodes ? opts.nodes[0] : document);
    }
  };
})();
